with ranked as (select *, rank() over (partition by dept_name order by budget) as latest_rank from departments qualify latest_rank = 1), enriched as (select *, ntile(3) over (order by budget desc, id) as budget_bucket, lag(budget, 1, 0) over (partition by location, dept_name order by latest_rank, id) as prev_budget, percent_rank() over w_running as budget_percent_rank, min(budget) over w_running_2 as dept_name_min_budget from ranked where location in ('Bangkok', 'Singapore', 'Chiang Mai') window w_running as (order by budget desc nulls first), w_running_2 as (partition by dept_name, location)), enriched_departments as (select id, location, budget, latest_rank, budget_bucket, budget_percent_rank, dept_name_min_budget, sum(budget) over w_ordered as cumulative_budget, lead(budget_bucket, 1) over (partition by location, dept_name order by dept_name_min_budget, id) as next_budget_bucket, avg(budget_percent_rank) over w_recent as budget_percent_rank_avg_6, ntile(3) over (partition by location order by budget_bucket desc, id) as budget_bucket_bucket, row_number() over w_running as row_seq from enriched window w_ordered as (partition by location, dept_name order by budget_bucket, id rows between unbounded preceding and current row), w_recent as (partition by dept_name order by prev_budget, id rows between 6 preceding and current row), w_running as (partition by location order by prev_budget desc, id)), eligible as (select s.* from enriched_departments s where not exists (select 1 from employees ch where ch.dept_id = s.id and ch.salary between 106000 and 134000)) select id, location, kpi, val from (select id, location, budget, budget_percent_rank from eligible) src unpivot include nulls (val for kpi in (budget, budget_percent_rank)) u;
